"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { useId, useMemo, useState } from "react"

import { setMenuOpen } from "@/components/ui/markdown-editor-adapter"
import {
  insertAtCaret,
  insertAtSelection,
  insertWikilink,
  replaceDocument,
  toggleFormat,
} from "@/components/ui/markdown-editor-commands"
import {
  markdownEditorLabelsEn,
  markdownEditorLabelsEs,
  type MarkdownEditorLabels,
} from "@/components/ui/markdown-editor-labels"
import { headingLevel, setHeading } from "@/components/ui/markdown-editor-lines"
import {
  MarkdownEditorMenus,
  markdownSlashCommands,
  type SlashCommand,
  type SuggestWikilinks,
} from "@/components/ui/markdown-editor-menus"
import { MarkdownEditorPortals } from "@/components/ui/markdown-editor-portals"
import { markdownDocument, markdownEditor, type MarkdownEditorHandle } from "@/components/ui/markdown-editor-primitive"
import { toggleTaskOnLine, type CodeLanguages, type EditorSettings } from "@/components/ui/markdown-editor-state"
import type { MarkdownConflict } from "@/components/ui/markdown-editor-sync"
import { MarkdownEditorToolbar } from "@/components/ui/markdown-editor-toolbar"
import { PortalStore } from "@/components/ui/markdown-editor-widgets"
import type { WikilinkResolver } from "@/components/ui/markdown-syntax"
import { fieldSurfaceClassName } from "@/components/ui/input"
import { useMarkdownEditorView } from "@/components/ui/use-markdown-editor"
import { cn } from "@/lib/utils"

const { Root: EditorRoot } = createParts(markdownEditor, { root: "div" })
const { Root: DocumentRoot } = createParts(markdownDocument, { root: "div" })

type MarkdownEditorProps = {
  /** Accessible name of the editor and its text box. */
  label: string
  value?: string
  defaultValue?: string
  /** Debounced by `changeDelay`; flushed on blur and unmount. Never called for `value` itself. */
  onChange?: (markdown: string) => void
  changeDelay?: number
  /** Whether the text differs from the last `value` (or `defaultValue`), counting edits `onChange` hasn't sent yet. */
  onDirtyChange?: (dirty: boolean) => void
  /**
   * Runs when a new `value` arrives while edits are still waiting for `onChange`. Return the text to keep, or
   * nothing to take `remote`. Without it, the local text goes out through `onChange` first, then `remote` applies.
   */
  onConflict?: (conflict: MarkdownConflict) => string | undefined | void
  readOnly?: boolean
  placeholder?: string
  resolveWikilink?: WikilinkResolver
  suggestWikilinks?: SuggestWikilinks
  onOpenWikilink?: (slug: string) => void
  slashCommands?: SlashCommand[]
  /** Languages for fenced code, loaded when a block first uses one; read once, at mount. */
  codeLanguages?: CodeLanguages
  /** Nonce for the style element CodeMirror injects, for pages with a strict Content Security Policy. */
  cspNonce?: string
  toolbar?: boolean
  labels?: Partial<MarkdownEditorLabels>
  className?: string
}

function MarkdownEditor(props: MarkdownEditorProps) {
  const { label, readOnly = false, placeholder, resolveWikilink, cspNonce, toolbar = true, className } = props
  const labels = useMemo(() => ({ ...markdownEditorLabelsEn, ...props.labels }), [props.labels])
  const slashCommands = useMemo(
    () => props.slashCommands ?? markdownSlashCommands(labels),
    [props.slashCommands, labels],
  )
  const hintId = useId()
  const [portals] = useState(() => new PortalStore())

  const settings = useMemo<EditorSettings>(
    () => ({
      label,
      describedBy: hintId,
      readOnly,
      placeholder,
      cspNonce,
      preview: { resolve: resolveWikilink, taskLabel: labels.task, portals },
    }),
    [label, hintId, readOnly, placeholder, cspNonce, resolveWikilink, labels.task, portals],
  )
  const { hostRef, view, adapter, sync } = useMarkdownEditorView(props, settings)

  const handle = useMemo<MarkdownEditorHandle | undefined>(() => {
    if (!view) return undefined
    return {
      getMarkdown: () => view.state.sliceDoc(),
      insertText: (text) => insertAtCaret(view, text),
      replaceSelection: (text) => insertAtSelection(view, text),
      insertWikilink: (slug, wikilinkLabel) => insertWikilink(view, slug, wikilinkLabel),
      toggleFormat: (format) => toggleFormat(view, format),
      setHeading: (level) => setHeading(view, level),
      toggleTask: (line) => toggleTaskOnLine(view, line),
      setMarkdown: (markdown) => {
        if (!replaceDocument(view, markdown)) sync.rebuild(markdown)
        return true
      },
    }
  }, [view, sync])

  return (
    <EditorRoot
      editor={handle}
      readOnly={readOnly}
      aria-label={label}
      className={cn(
        `${fieldSurfaceClassName} flex min-h-0 flex-col overflow-hidden rounded-choice text-body has-[.cm-focused]:ring-2 has-[.cm-focused]:ring-ring data-readonly:bg-transparent data-readonly:shadow-none`,
        className,
      )}
    >
      {toolbar && !readOnly && (
        <MarkdownEditorToolbar
          labels={labels}
          headingLevel={() => (view ? headingLevel(view.state) : 0)}
          restoreFocus={() => view?.contentDOM ?? null}
          onFormat={(format) => {
            if (!view) return
            toggleFormat(view, format)
            view.focus()
          }}
          onHeading={(level) => {
            if (!view) return
            setHeading(view, level)
            view.focus()
          }}
        />
      )}
      <DocumentRoot
        editor={handle}
        readOnly={readOnly}
        agentConfirm={labels.setMarkdownConfirm}
        aria-label={labels.document}
        className="min-h-0 flex-1 overflow-auto"
      >
        <div ref={hostRef} data-slot="markdown-editor-content" className="h-full" />
      </DocumentRoot>
      <p id={hintId} hidden>
        {labels.usageHint}
      </p>
      <MarkdownEditorPortals store={portals} labels={labels} options={{ resolveWikilink, taskLabel: labels.task }} />
      {!readOnly && (
        <MarkdownEditorMenus
          adapter={adapter}
          view={view}
          slashCommands={slashCommands}
          suggestWikilinks={props.suggestWikilinks}
          emptyLabel={labels.noMatches}
          onOpenChange={(open) => view?.dispatch({ effects: setMenuOpen.of(open) })}
        />
      )}
    </EditorRoot>
  )
}

export { MarkdownEditor, markdownEditorLabelsEn, markdownEditorLabelsEs, markdownSlashCommands }
export type { MarkdownConflict, MarkdownEditorLabels, MarkdownEditorProps, SlashCommand, SuggestWikilinks }

import { StateEffect, StateField, type Extension } from "@codemirror/state"
import { EditorView, keymap, type KeyBinding } from "@codemirror/view"
import type { EditorChange, TextEditorAdapter } from "@ui-sdk/react/trigger-menu"

import { toDocText } from "@/components/ui/markdown-editor-commands"

const setMenuOpen = StateEffect.define<boolean>()
const menuOpen = StateField.define<boolean>({
  create: () => false,
  update: (open, transaction) => {
    for (const effect of transaction.effects) if (effect.is(setMenuOpen)) open = effect.value
    return open
  },
})

const MENU_KEYS = new Set(["Enter", "ArrowUp", "ArrowDown", "Tab", "Escape", "Home", "End", "PageUp", "PageDown"])

/**
 * CodeMirror's keydown listener sits on the content element before the menu's and prevents default when a
 * binding runs, which the menu respects. While the menu is open, its keys skip every binding instead.
 */
function menuAwareKeymap(bindings: readonly KeyBinding[]): Extension {
  return [
    menuOpen,
    keymap.of(
      bindings.map((binding) => {
        if (!binding.key || !MENU_KEYS.has(binding.key)) return binding
        const { run, shift } = binding
        return {
          ...binding,
          preventDefault: false,
          run: run && ((view) => !view.state.field(menuOpen) && run(view)),
          shift: shift && ((view) => !view.state.field(menuOpen) && shift(view)),
        }
      }),
    ),
  ]
}

/** The listener extension must be in the state before the view exists; the adapter attaches once it does. */
function createAdapterBridge() {
  const listeners = new Set<(change: EditorChange) => void>()
  const emit = (change: EditorChange) => listeners.forEach((listener) => listener(change))

  const extension = EditorView.updateListener.of((update) => {
    if (!listeners.size) return
    for (const transaction of update.transactions) {
      if (!transaction.docChanged) continue
      const user =
        transaction.isUserEvent("input.type") ||
        transaction.isUserEvent("input.paste") ||
        transaction.isUserEvent("delete")
      transaction.changes.iterChanges((fromA, toA, _fromB, _toB, inserted) =>
        emit({ type: "input", inserted: inserted.toString(), range: { start: fromA, end: toA }, user }),
      )
    }
    if (update.selectionSet && !update.docChanged) emit({ type: "selection" })
  })

  const onStart = () => emit({ type: "compositionstart" })
  const onEnd = () => emit({ type: "compositionend" })

  function attach(view: EditorView) {
    view.contentDOM.addEventListener("compositionstart", onStart)
    view.contentDOM.addEventListener("compositionend", onEnd)

    const adapter: TextEditorAdapter = {
      get element() {
        return view.contentDOM
      },
      textBefore(length) {
        const head = view.state.selection.main.head
        const offset = Math.max(0, head - length)
        return { text: view.state.doc.sliceString(offset, head, "\n"), offset }
      },
      selection() {
        if (!view.hasFocus) return null
        const { from, to } = view.state.selection.main
        return { start: from, end: to }
      },
      rectAt(offset) {
        const rect = view.coordsAtPos(Math.min(offset, view.state.doc.length))
        return rect && { x: rect.left, y: rect.top, width: rect.right - rect.left, height: rect.bottom - rect.top }
      },
      replace(range, content) {
        const text = toDocText(view.state, typeof content === "string" ? content : content.label)
        view.dispatch({
          changes: { from: range.start, to: range.end, insert: text },
          selection: { anchor: range.start + view.state.toText(text).length },
          userEvent: "input.complete",
          scrollIntoView: true,
        })
      },
      subscribe(listener) {
        listeners.add(listener)
        return () => listeners.delete(listener)
      },
      composing: () => view.composing,
    }

    const detach = () => {
      view.contentDOM.removeEventListener("compositionstart", onStart)
      view.contentDOM.removeEventListener("compositionend", onEnd)
      listeners.clear()
    }
    return { adapter, detach }
  }

  return { extension, attach }
}

export { createAdapterBridge, menuAwareKeymap, menuOpen, setMenuOpen }

import { syntaxTree } from "@codemirror/language"
import { EditorSelection, StateField, type EditorState, type Range, type Transaction } from "@codemirror/state"
import { Decoration, EditorView, type DecorationSet } from "@codemirror/view"

import { previewConfig } from "@/components/ui/markdown-editor-preview"
import type { Span } from "@/components/ui/markdown-editor-structure"
import { TableWidget } from "@/components/ui/markdown-editor-widgets"

type Block = Span & { table: boolean }
type Blocks = { tables: Span[]; underlines: Span[]; shown: Block[]; decorations: DecorationSet }

const CONTAINERS = new Set(["Document", "Blockquote", "BulletList", "OrderedList", "ListItem"])
const hideUnderline = Decoration.replace({})

function scan(state: EditorState, from = 0, to = state.doc.length) {
  const tables: Span[] = []
  const underlines: Span[] = []
  syntaxTree(state).iterate({
    from,
    to,
    enter(ref) {
      if (CONTAINERS.has(ref.name)) return undefined
      if (ref.from < from || ref.to > to) return false
      if (ref.name === "Table" && ref.node.parent?.name === "Document") tables.push({ from: ref.from, to: ref.to })
      else if (ref.name.startsWith("SetextHeading")) {
        const underline = ref.node.lastChild
        if (underline?.name === "HeaderMark") underlines.push({ from: underline.from, to: underline.to })
      }
      return false
    },
  })
  return { tables, underlines }
}

/** Start and end of the top-level blocks around `from` and `to`. */
function topLevel(state: EditorState, from: number, to: number) {
  const tree = syntaxTree(state)
  const outer = (pos: number, side: -1 | 1) => {
    let node = tree.resolve(pos, side)
    while (node.parent && node.parent.parent) node = node.parent
    return node.parent ? node : null
  }
  return { from: Math.min(from, outer(from, -1)?.from ?? from), to: Math.max(to, outer(to, 1)?.to ?? to) }
}

/**
 * Rescans only the top-level blocks an edit touched, in the old tree and the new one, so an edit that opens or
 * closes a fence still rescans everything the fence swallowed or let go.
 */
function rescan(blocks: Blocks, transaction: Transaction) {
  const { state, startState, changes } = transaction
  if (!changes.empty && syntaxTree(state).length < state.doc.length) return scan(state)
  let from = state.doc.length
  let to = 0
  changes.iterChangedRanges((fromA, toA, fromB, toB) => {
    const before = topLevel(startState, fromA, toA)
    const after = topLevel(state, fromB, toB)
    from = Math.min(from, after.from, changes.mapPos(before.from, -1))
    to = Math.max(to, after.to, changes.mapPos(before.to, 1))
  })
  if (from > to) return scan(state)
  const outside = (span: Span) => span.to < from || span.from > to
  const map = (span: Span) => ({ from: changes.mapPos(span.from, 1), to: changes.mapPos(span.to, -1) })
  const found = scan(state, from, to)
  const merge = (old: Span[], fresh: Span[]) =>
    [...old.map(map).filter(outside), ...fresh].toSorted((a, b) => a.from - b.from)
  return { tables: merge(blocks.tables, found.tables), underlines: merge(blocks.underlines, found.underlines) }
}

/** The tables to render and the underlines to hide, given where the selection is. */
function plan(state: EditorState, tables: Span[], underlines: Span[]) {
  const ranges = state.readOnly ? [] : state.selection.ranges
  const touched = (from: number, to: number) => ranges.some((range) => range.from <= to && range.to >= from)
  const shown: Block[] = []
  if (state.facet(previewConfig).portals) {
    for (const table of tables) if (!touched(table.from, table.to)) shown.push({ ...table, table: true })
  }
  for (const underline of underlines) {
    const current = state.doc.lineAt(underline.from)
    if (current.number > 1 && !touched(current.from, current.to)) {
      shown.push({ from: current.from - 1, to: current.to, table: false })
    }
  }
  return shown.toSorted((a, b) => a.from - b.from)
}

// Block widgets and hidden line breaks may only come from a state field, not from a view plugin.
function decorate(state: EditorState, shown: Block[]) {
  const portals = state.facet(previewConfig).portals
  const decorations: Range<Decoration>[] = shown.map((block) => {
    if (!block.table || !portals) return hideUnderline.range(block.from, block.to)
    const rows = state.doc.lineAt(block.to).number - state.doc.lineAt(block.from).number
    const widget = new TableWidget(state.sliceDoc(block.from, block.to), portals, rows)
    return Decoration.replace({ widget, block: true }).range(block.from, block.to)
  })
  return Decoration.set(decorations)
}

const blockPreview = StateField.define<Blocks>({
  create(state) {
    const { tables, underlines } = scan(state)
    const shown = plan(state, tables, underlines)
    return { tables, underlines, shown, decorations: decorate(state, shown) }
  },
  update(blocks, transaction: Transaction) {
    const { state, startState } = transaction
    if (transaction.isUserEvent("input.type.compose")) {
      return { ...blocks, decorations: blocks.decorations.map(transaction.changes) }
    }
    const reparsed = syntaxTree(startState) !== syntaxTree(state)
    const reconfigured = startState.facet(previewConfig) !== state.facet(previewConfig)
    if (!reparsed && !transaction.docChanged && !reconfigured && !transaction.selection) {
      if (startState.readOnly === state.readOnly) return blocks
    }
    // A parse that moved on without an edit can change structure anywhere, so it gets a full scan.
    const { tables, underlines } = transaction.docChanged
      ? rescan(blocks, transaction)
      : reparsed
        ? scan(state)
        : blocks
    const shown = plan(state, tables, underlines)
    // Most transactions leave every rendered block as it was, so the widgets are mapped instead of rebuilt.
    const { changes } = transaction
    const same =
      !reconfigured &&
      shown.length === blocks.shown.length &&
      blocks.shown.every((block, index) => {
        const next = shown[index]!
        if (block.table && changes.touchesRange(block.from, block.to)) return false
        return (
          next.table === block.table && next.from === changes.mapPos(block.from) && next.to === changes.mapPos(block.to)
        )
      })
    const decorations = same ? blocks.decorations.map(changes) : decorate(state, shown)
    return { tables, underlines, shown, decorations }
  },
  provide: (field) => [
    EditorView.decorations.from(field, (blocks) => blocks.decorations),
    EditorView.atomicRanges.of((view) => view.state.field(field).decorations),
    EditorView.domEventHandlers({ mousedown: selectTableCell }),
  ],
})

/** A press on a rendered table puts the caret in the cell it hit, which shows the table's source. */
function selectTableCell(event: MouseEvent, view: EditorView) {
  const target = event.target instanceof Element ? event.target : null
  const host = target?.closest<HTMLElement>("[data-slot=markdown-table-widget]")
  if (!host || event.button !== 0) return false
  const cell = target?.closest<HTMLElement>("[data-source-from]")
  const pos = Math.min(view.posAtDOM(host) + Number(cell?.dataset.sourceFrom ?? 0), view.state.doc.length)
  view.dispatch({ selection: EditorSelection.cursor(pos), userEvent: "select.pointer" })
  view.focus()
  event.preventDefault()
  return true
}

export { blockPreview }

import { EditorSelection, EditorState, type Annotation, type ChangeSpec, type Extension } from "@codemirror/state"
import { EditorView } from "@codemirror/view"

import { headingLevel, setHeading } from "@/components/ui/markdown-editor-lines"
import { wikilinkText } from "@/components/ui/markdown-syntax"

type InlineFormat = "bold" | "italic" | "strikethrough" | "code"
type LineFormat = "heading" | "quote" | "bulletList" | "orderedList" | "taskList"
type MarkdownFormat = InlineFormat | LineFormat | "link"

const INLINE_MARKERS: Record<InlineFormat, string> = { bold: "**", italic: "_", strikethrough: "~~", code: "`" }
const LINE_PREFIXES: Record<LineFormat, { add: string; match: RegExp }> = {
  heading: { add: "## ", match: /^#{1,6} / },
  quote: { add: "> ", match: /^> ?/ },
  bulletList: { add: "- ", match: /^[-*+] (?!\[[ xX]\] )/ },
  orderedList: { add: "1. ", match: /^\d+[.)] / },
  taskList: { add: "- [ ] ", match: /^[-*+] \[[ xX]\] / },
}

const FORMATS = [...Object.keys(INLINE_MARKERS), ...Object.keys(LINE_PREFIXES), "link"] as MarkdownFormat[]

/** The document's line break, so CRLF files keep CRLF; mixed files keep every byte by splitting on "\n" only. */
function lineSeparatorOf(text: string) {
  const crlf = text.split("\r\n").length - 1
  const lf = text.split("\n").length - 1
  return crlf > 0 && crlf === lf && !/\r(?!\n)/.test(text) ? "\r\n" : "\n"
}

function lineSeparatorExtension(text: string): Extension {
  const separator = lineSeparatorOf(text)
  if (separator === "\n") return EditorState.lineSeparator.of("\n")
  return [
    EditorState.lineSeparator.of(separator),
    EditorView.clipboardInputFilter.of((input) => input.replace(/\r\n?|\n/g, separator)),
  ]
}

function toDocText(state: EditorState, text: string) {
  return state.lineBreak === "\n" ? text : text.replace(/\r\n?|\n/g, state.lineBreak)
}

/** Common prefix and suffix, in document positions (one per line break), never splitting a surrogate pair. */
function minimalChange(current: string, next: string) {
  let start = 0
  const max = Math.min(current.length, next.length)
  while (start < max && current.charCodeAt(start) === next.charCodeAt(start)) start++
  if (start > 0 && /[\uD800-\uDBFF]/.test(current.charAt(start - 1))) start--
  let end = 0
  while (end < max - start && current.charCodeAt(current.length - 1 - end) === next.charCodeAt(next.length - 1 - end)) {
    end++
  }
  if (end > 0 && /[\uDC00-\uDFFF]/.test(current.charAt(current.length - end))) end--
  return { from: start, to: current.length - end, insert: next.slice(start, next.length - end) }
}

const flat = (state: EditorState, text: string) =>
  state.lineBreak === "\n" ? text : text.replaceAll(state.lineBreak, "\n")

/** Returns false when `next` needs a different line separator, so the caller must rebuild the state instead. */
function replaceDocument(view: EditorView, next: string, annotations: Annotation<unknown>[] = []) {
  const { state } = view
  if (lineSeparatorOf(next) !== state.lineBreak) return false
  const change = minimalChange(state.doc.sliceString(0, undefined, "\n"), flat(state, next))
  if (change.from === change.to && change.insert === "") return true
  view.dispatch({ changes: { ...change, insert: toDocText(state, change.insert) }, annotations })
  return true
}

function toggleInline(view: EditorView, format: InlineFormat) {
  const marker = INLINE_MARKERS[format]
  const size = marker.length
  const { state } = view
  view.dispatch(
    state.changeByRange((range) => {
      const before = state.sliceDoc(range.from - size, range.from)
      const after = state.sliceDoc(range.to, range.to + size)
      if (before === marker && after === marker) {
        return {
          changes: [
            { from: range.from - size, to: range.from },
            { from: range.to, to: range.to + size },
          ],
          range: EditorSelection.range(range.from - size, range.to - size),
        }
      }
      const inner = state.sliceDoc(range.from, range.to)
      if (inner.length >= size * 2 && inner.startsWith(marker) && inner.endsWith(marker)) {
        return {
          changes: { from: range.from, to: range.to, insert: inner.slice(size, -size) },
          range: EditorSelection.range(range.from, range.to - size * 2),
        }
      }
      return {
        changes: [
          { from: range.from, insert: marker },
          { from: range.to, insert: marker },
        ],
        range: EditorSelection.range(range.from + size, range.to + size),
      }
    }),
    { userEvent: "input.format", scrollIntoView: true },
  )
}

function toggleLines(view: EditorView, format: LineFormat) {
  const { add, match } = LINE_PREFIXES[format]
  const { state } = view
  const lines = new Map<number, { from: number; text: string }>()
  for (const range of state.selection.ranges) {
    for (let pos = range.from; pos <= range.to;) {
      const current = state.doc.lineAt(pos)
      lines.set(current.number, { from: current.from, text: current.text })
      pos = current.to + 1
    }
  }
  const all = [...lines.values()]
  const remove = all.every((entry) => match.test(entry.text))
  const changes: ChangeSpec[] = all.map((entry) => {
    const existing = match.exec(entry.text)?.[0]
    if (remove) return { from: entry.from, to: entry.from + (existing?.length ?? 0) }
    const other = Object.values(LINE_PREFIXES)
      .find((prefix) => prefix.match.test(entry.text))
      ?.match.exec(entry.text)?.[0]
    return { from: entry.from, to: entry.from + (other?.length ?? 0), insert: add }
  })
  view.dispatch({ changes, userEvent: "input.format", scrollIntoView: true })
}

function toggleFormat(view: EditorView, format: MarkdownFormat) {
  if (!FORMATS.includes(format))
    throw new RangeError(`Unknown format "${String(format)}". Formats: ${FORMATS.join(", ")}.`)
  if (view.state.readOnly) return false
  if (format === "heading") return setHeading(view, headingLevel(view.state) ? 0 : 2)
  if (format === "link") {
    const range = view.state.selection.main
    const text = view.state.sliceDoc(range.from, range.to)
    const insert = `[${text}](url)`
    const urlStart = range.from + text.length + 3
    view.dispatch({
      changes: { from: range.from, to: range.to, insert },
      selection: EditorSelection.range(urlStart, urlStart + 3),
      userEvent: "input.format",
    })
  } else if (format in INLINE_MARKERS) {
    toggleInline(view, format as InlineFormat)
  } else {
    toggleLines(view, format as LineFormat)
  }
  return true
}

function insertAtSelection(view: EditorView, text: string, userEvent = "input") {
  if (view.state.readOnly) return false
  const insert = toDocText(view.state, text)
  view.dispatch(view.state.replaceSelection(insert), { userEvent, scrollIntoView: true })
  return true
}

/** Inserts at the caret without replacing the selected text, and puts the caret after the insertion. */
function insertAtCaret(view: EditorView, text: string, userEvent = "input") {
  if (view.state.readOnly) return false
  const insert = toDocText(view.state, text)
  const at = view.state.selection.main.head
  view.dispatch({
    changes: { from: at, insert },
    selection: { anchor: at + view.state.toText(insert).length },
    userEvent,
    scrollIntoView: true,
  })
  return true
}

function insertWikilink(view: EditorView, slug: string, label?: string) {
  if (!slug.trim() || /[[\]|\r\n]/.test(slug)) throw new RangeError(`"${slug}" isn't a valid wikilink target.`)
  return insertAtCaret(view, wikilinkText(slug, label), "input.wikilink")
}

