import { syntaxTree } from "@codemirror/language"
import type { EditorState, Range } from "@codemirror/state"
import { Decoration } from "@codemirror/view"
import type { SyntaxNode } from "@lezer/common"

import type { Span } from "@/components/ui/markdown-editor-structure"
import { CodeLanguageWidget, LabelWidget, type PortalStore } from "@/components/ui/markdown-editor-widgets"
import type { WikilinkResolver } from "@/components/ui/markdown-syntax"

const hidden = Decoration.replace({})
const cache = new Map<string, Decoration>()
function mark(attributes: Record<string, string>) {
  const key = JSON.stringify(attributes)
  let decoration = cache.get(key)
  if (!decoration) cache.set(key, (decoration = Decoration.mark({ attributes })))
  return decoration
}
function line(attributes: Record<string, string>) {
  const key = `line${JSON.stringify(attributes)}`
  let decoration = cache.get(key)
  if (!decoration) cache.set(key, (decoration = Decoration.line({ attributes })))
  return decoration
}
const slot = (name: string, extra: Record<string, string> = {}) => mark({ "data-slot": name, ...extra })
const syntax = slot("markdown-syntax")

const SPANS: Record<string, { slot: string; marks: string[] }> = {
  Emphasis: { slot: "markdown-emphasis", marks: ["EmphasisMark"] },
  StrongEmphasis: { slot: "markdown-strong", marks: ["EmphasisMark"] },
  Strikethrough: { slot: "markdown-strike", marks: ["StrikethroughMark"] },
  InlineCode: { slot: "markdown-code", marks: ["CodeMark"] },
  Link: { slot: "markdown-link", marks: ["LinkMark", "URL", "LinkTitle", "LinkLabel"] },
  Image: { slot: "markdown-link", marks: ["LinkMark", "URL", "LinkTitle", "LinkLabel"] },
  Autolink: { slot: "markdown-link", marks: ["LinkMark"] },
}
const SPAN_MARKS = new Set(Object.values(SPANS).flatMap((span) => span.marks))
const HTML = new Set(["HTMLTag", "HTMLBlock", "Comment", "ProcessingInstruction"])

type TreeContext = {
  state: EditorState
  ranges: Range<Decoration>[]
  revealed: (from: number, to: number) => boolean
  resolve?: WikilinkResolver
  portals?: PortalStore
}

function decorateTree(context: TreeContext, from: number, to: number) {
  const { state, ranges, revealed } = context
  const doc = state.doc
  // A plugin may not hide a line break, and syntax such as a link title can span lines, so hide line by line.
  const hide = (start: number, end: number) => {
    for (let pos = start; pos < end;) {
      const current = doc.lineAt(pos)
      const stop = Math.min(end, current.to)
      if (stop > pos) ranges.push(hidden.range(pos, stop))
      pos = current.to + 1
    }
  }
  const eachLine = (start: number, end: number, decoration: Decoration) => {
    for (let pos = start; pos <= end;) {
      const current = doc.lineAt(pos)
      ranges.push(decoration.range(current.from))
      pos = current.to + 1
    }
  }

  syntaxTree(state).iterate({
    from,
    to,
    enter(ref) {
      const node = ref.node
      const heading = /^(ATX|Setext)Heading(\d)$/.exec(node.name)
      if (heading) {
        const textEnd = heading[1] === "Setext" ? (node.lastChild?.from ?? node.to) - 1 : node.to
        eachLine(node.from, Math.max(node.from, textEnd), line({ "data-md-heading": heading[2] ?? "1" }))
        return undefined
      }
      const span = SPANS[node.name]
      if (span) {
        ranges.push(slot(span.slot).range(node.from, node.to))
        const show = revealed(node.from, node.to)
        for (let child = node.firstChild; child; child = child.nextSibling) {
          if (!span.marks.includes(child.name)) continue
          if (show) ranges.push(syntax.range(child.from, child.to))
          else hide(child.from, child.to)
        }
        return undefined
      }
      switch (node.name) {
        case "HeaderMark":
          if (node.parent?.name.startsWith("Setext")) ranges.push(syntax.range(node.from, node.to))
          else if (node.prevSibling) {
            let start = node.from
            while (start > 0 && doc.sliceString(start - 1, start) === " ") start--
            hide(start, node.to)
          }
          return false
        case "Escape":
          if (!revealed(node.from, node.to)) hide(node.from, node.from + 1)
          return false
        case "Wikilink":
          decorateWikilink(context, node, hide)
          return false
        case "FencedCode":
          decorateFence(context, node, hide)
          return false
        case "CodeBlock":
          eachLine(node.from, node.to, line({ "data-md-code": "" }))
          return false
        case "HorizontalRule":
          ranges.push(line({ "data-md-rule": "" }).range(doc.lineAt(node.from).from))
          if (!revealed(node.from, node.to)) hide(node.from, node.to)
          return false
        case "Table":
          decorateTable(context, node)
          return false
        case "LinkReference":
          ranges.push(syntax.range(node.from, node.to))
          return false
        default:
          if (HTML.has(node.name)) {
            ranges.push(slot("markdown-html").range(node.from, node.to))
            return false
          }
          return SPAN_MARKS.has(node.name) ? false : undefined
      }
    },
  })
}

function decorateFence(context: TreeContext, node: SyntaxNode, hide: (from: number, to: number) => void) {
  const { state, ranges, revealed } = context
  const doc = state.doc
  const open = node.firstChild
  const close = node.lastChild?.name === "CodeMark" && node.lastChild !== open ? node.lastChild : null
  const openLine = doc.lineAt(node.from)
  const closeLine = close ? doc.lineAt(close.from) : null
  for (let pos = node.from; pos <= node.to;) {
    const current = doc.lineAt(pos)
    const fence = current.number === openLine.number ? "open" : current.number === closeLine?.number ? "close" : ""
    ranges.push(line({ "data-md-code": fence }).range(current.from))
    pos = current.to + 1
  }
  if (open?.name !== "CodeMark") return
  const info = node.getChild("CodeInfo")
  if (revealed(openLine.from, openLine.to)) {
    ranges.push(syntax.range(open.from, info?.to ?? open.to))
  } else if (context.portals) {
    const widget = new CodeLanguageWidget(info ? state.sliceDoc(info.from, info.to) : "", context.portals)
    ranges.push(Decoration.replace({ widget }).range(open.from, openLine.to))
  } else {
    hide(open.from, openLine.to)
  }
  if (close && closeLine) {
    if (revealed(closeLine.from, closeLine.to)) ranges.push(syntax.range(close.from, close.to))
    else hide(close.from, closeLine.to)
  }
}

function decorateTable(context: TreeContext, table: SyntaxNode) {
  const { state, ranges } = context
  const doc = state.doc
  const cell = (from: number, to: number, column: number) => {
    if (to <= from) return
    const attributes = { "data-slot": "markdown-table-cell", "data-md-table-id": String(table.from) }
    ranges.push(mark({ ...attributes, "data-md-column": String(column) }).range(from, to))
  }
  for (let row = table.firstChild; row; row = row.nextSibling) {
    const current = doc.lineAt(row.from)
    if (row.name === "TableDelimiter") {
      ranges.push(line({ "data-md-table": "delimiter" }).range(current.from))
      const text = state.sliceDoc(row.from, row.to)
      let column = text.startsWith("|") ? -1 : 0
      let start = row.from
      for (let index = 0; index <= text.length; index++) {
        if (index < text.length && text[index] !== "|") continue
        const pos = row.from + index
        if (column >= 0) cell(start, pos, column)
        if (index < text.length) ranges.push(syntax.range(pos, pos + 1))
        column++
        start = pos + 1
      }
      continue
    }
    if (row.name !== "TableHeader" && row.name !== "TableRow") continue
    ranges.push(line({ "data-md-table": row.name === "TableHeader" ? "header" : "row" }).range(current.from))
    const pipes = row.getChildren("TableDelimiter")
    let start = row.from
    let column = pipes[0]?.from === row.from ? -1 : 0
    for (const pipe of [...pipes, null]) {
      const end = pipe ? pipe.from : row.to
      if (column >= 0 && (pipe || end > start)) cell(start, end, column)
      if (pipe) ranges.push(syntax.range(pipe.from, pipe.to))
      column++
      start = pipe ? pipe.to : end
    }
  }
}

function decorateWikilink(context: TreeContext, node: SyntaxNode, hide: (from: number, to: number) => void) {
  const { state, ranges } = context
  const target = node.getChild("WikilinkTarget")
  if (!target) return
  const slug = state.sliceDoc(target.from, target.to).trim()
  const resolution = context.resolve?.(slug) ?? { exists: true }
  ranges.push(slot("markdown-wikilink", resolution.exists ? {} : { "data-unresolved": "" }).range(node.from, node.to))
  const label = node.getChild("WikilinkLabel")
  const show = context.revealed(node.from, node.to)
  for (let child = node.firstChild; child; child = child.nextSibling) {
    const isSyntax = child.name === "WikilinkMark" || child.name === "WikilinkPipe"
    if (show) {
      if (isSyntax) ranges.push(syntax.range(child.from, child.to))
    } else if (isSyntax || (child.name === "WikilinkTarget" && label)) {
      hide(child.from, child.to)
    } else if (child.name === "WikilinkTarget" && resolution.label && resolution.label !== slug) {
      ranges.push(Decoration.replace({ widget: new LabelWidget(resolution.label) }).range(child.from, child.to))
    }
  }
}

export { decorateTree, hidden, line, slot }
export type { Span, TreeContext }

import { syntaxTree } from "@codemirror/language"
import type { ChangeSpec, EditorState, Line } from "@codemirror/state"
import type { EditorView } from "@codemirror/view"
import type { SyntaxNode } from "@lezer/common"

import { lineStructure } from "@/components/ui/markdown-editor-structure"

function selectedLines(state: EditorState) {
  const lines = new Map<number, Line>()
  for (const range of state.selection.ranges) {
    for (let pos = range.from; pos <= range.to;) {
      const current = state.doc.lineAt(pos)
      lines.set(current.number, current)
      pos = current.to + 1
    }
  }
  return [...lines.values()]
}

function headingAt(state: EditorState, line: Line): SyntaxNode | null {
  for (let node: SyntaxNode | null = syntaxTree(state).resolveInner(line.to, -1); node; node = node.parent) {
    if (/^(ATX|Setext)Heading\d$/.test(node.name)) return node
  }
  return null
}

function headingLevel(state: EditorState, pos = state.selection.main.head) {
  const heading = headingAt(state, state.doc.lineAt(pos))
  return heading ? Number(heading.name.slice(-1)) : 0
}

/** Level 0 turns the line into a paragraph. A setext heading keeps its underline for levels 1 and 2. */
function setHeading(view: EditorView, level: number) {
  if (!Number.isInteger(level) || level < 0 || level > 6) {
    throw new RangeError(`Heading level must be 0 to 6, got ${String(level)}.`)
  }
  const { state } = view
  if (state.readOnly) return false
  const changes: ChangeSpec[] = []
  const done = new Set<number>()
  for (const line of selectedLines(state)) {
    const heading = headingAt(state, line)
    if (heading && done.has(heading.from)) continue
    if (heading?.name.startsWith("Setext")) {
      done.add(heading.from)
      const underline = heading.lastChild
      if (!underline) continue
      const underlineLine = state.doc.lineAt(underline.from)
      if (level === 1 || level === 2) {
        const insert = (level === 1 ? "=" : "-").repeat(underline.to - underline.from)
        changes.push({ from: underline.from, to: underline.to, insert })
      } else {
        changes.push({ from: underlineLine.from - 1, to: underlineLine.to })
        if (level > 2) changes.push({ from: heading.from, insert: `${"#".repeat(level)} ` })
      }
      continue
    }
    const structure = lineStructure(state, line)
    const prefix = level ? `${"#".repeat(level)} ` : ""
    if (heading) {
      done.add(heading.from)
      const mark = heading.firstChild
      if (!mark || mark.name !== "HeaderMark") continue
      changes.push({ from: mark.from, to: structure.contentStart, insert: prefix })
    } else if (level) {
      changes.push({ from: structure.contentStart, insert: prefix })
    }
  }
  if (!changes.length) return true
  view.dispatch({ changes, userEvent: "input.format", scrollIntoView: true })
  return true
}

const column = (state: EditorState, pos: number) => pos - state.doc.lineAt(pos).from

function listItems(state: EditorState) {
  const items: SyntaxNode[] = []
  for (const line of selectedLines(state)) {
    const item = lineStructure(state, line).listItem
    if (item && !items.some((other) => other.from <= item.from && other.to >= item.to)) items.push(item)
  }
  return items
}

/** Shifts every line of an item, its children included, by `delta` spaces, after any quote marks. */
function shiftItem(state: EditorState, item: SyntaxNode, delta: number, changes: ChangeSpec[]) {
  const first = state.doc.lineAt(item.from)
  let quoted = false
  for (let node = item.parent; node; node = node.parent) if (node.name === "Blockquote") quoted = true
  const quotePrefix = (text: string) => (quoted ? (/^(?:\s*>\s?)*/.exec(text)?.[0].length ?? 0) : 0)
  for (let pos = item.from; pos <= item.to;) {
    const current = state.doc.lineAt(pos)
    pos = current.to + 1
    if (!current.text.trim()) continue
    const isFirst = current.number === first.number
    const at = isFirst ? item.from : current.from + quotePrefix(current.text)
    if (delta > 0) {
      changes.push({ from: at, insert: " ".repeat(delta) })
      continue
    }
    const spaces = isFirst
      ? (/ *$/.exec(state.sliceDoc(current.from, at))?.[0].length ?? 0)
      : (/^ */.exec(state.sliceDoc(at, current.to))?.[0].length ?? 0)
    const count = Math.min(-delta, spaces)
    if (count > 0) changes.push(isFirst ? { from: at - count, to: at } : { from: at, to: at + count })
  }
}

function contentColumn(state: EditorState, item: SyntaxNode) {
  const mark = item.getChild("ListMark")
  if (!mark) return column(state, item.from)
  const line = state.doc.lineAt(mark.from)
  let end = mark.to
  while (end < line.to && state.sliceDoc(end, end + 1) === " ") end++
  return end - line.from
}

function indentList(view: EditorView) {
  const { state } = view
  const items = listItems(state)
  if (!items.length || state.readOnly) return false
  const changes: ChangeSpec[] = []
  for (const item of items) {
    const previous = item.prevSibling
    if (previous?.name !== "ListItem") continue
    const delta = contentColumn(state, previous) - column(state, item.from)
    if (delta > 0) shiftItem(state, item, delta, changes)
  }
  if (changes.length) view.dispatch({ changes, userEvent: "input.indent" })
  return true
}

function outdentList(view: EditorView) {
  const { state } = view
  const items = listItems(state)
  if (!items.length || state.readOnly) return false
  const changes: ChangeSpec[] = []
  for (const item of items) {
    const parent = item.parent?.parent
    if (parent?.name !== "ListItem") continue
    const delta = column(state, item.from) - column(state, parent.from)
    if (delta > 0) shiftItem(state, item, -delta, changes)
  }
  if (changes.length) view.dispatch({ changes, userEvent: "delete.dedent" })
  return true
}

/**
 * Backspace at the start of a line's text removes its innermost marker: a task box, then a nested item's
 * indentation, a list marker, a heading or a quote, instead of deleting the hidden marks all at once.
 */
function deleteMarker(view: EditorView) {
  const { state } = view
  const range = state.selection.main
  if (state.readOnly || !range.empty || state.selection.ranges.length > 1) return false
  const line = state.doc.lineAt(range.head)
  const structure = lineStructure(state, line)
  if (range.head !== structure.contentStart || structure.contentStart === line.from || structure.continuation) {
    return false
  }
  const dispatch = (from: number, to: number) => {
    view.dispatch({ changes: { from, to }, userEvent: "delete.marker", scrollIntoView: true })
    return true
  }
  if (structure.task) return dispatch(structure.task.from, structure.contentStart)
  if (structure.listItem) {
    if (structure.depth > 1) return outdentList(view)
    return dispatch((structure.bullet ?? structure.ordered)!.from, structure.contentStart)
  }
  if (structure.heading) return setHeading(view, 0)
  const quote = structure.hidden.at(-1)
  return quote ? dispatch(quote.from, quote.to) : false
}

export { deleteMarker, headingLevel, indentList, outdentList, setHeading }

"use client"

import type { EditorView } from "@codemirror/view"
import {
  TriggerMenu,
  TriggerMenuContent,
  TriggerMenuEmpty,
  TriggerMenuItem,
  TriggerMenuList,
  TriggerMenuStatus,
  type TextEditorAdapter,
  type TriggerDefinition,
  type TriggerMenuDataItem,
} from "@ui-sdk/react/trigger-menu"
import { useMemo, type ReactNode } from "react"

import { toDocText, toggleFormat, type MarkdownFormat } from "@/components/ui/markdown-editor-commands"
import { markdownEditorLabelsEn, type MarkdownEditorLabels } from "@/components/ui/markdown-editor-labels"
import { setHeading } from "@/components/ui/markdown-editor-lines"
import { wikilinkText } from "@/components/ui/markdown-syntax"

type SlashCommand = {
  value: string
  label: string
  keywords?: string[]
  hint?: string
  /** Replaces the typed `/query` (from `from` to `to`) with whatever the command inserts. */
  run: (view: EditorView, range: { from: number; to: number }) => void
}

type WikilinkSuggestion = { slug: string; label?: string }
type SuggestWikilinks = (query: string, context: { signal: AbortSignal }) => Promise<WikilinkSuggestion[]>

function insertBlock(text: string, caret = text.length): SlashCommand["run"] {
  return (view, { from, to }) => {
    const line = view.state.doc.lineAt(from)
    const lead = view.state.sliceDoc(line.from, from).trim() ? "\n\n" : ""
    const block = lead + text
    const insert = toDocText(view.state, block)
    const offset = toDocText(view.state, block.slice(0, lead.length + caret)).length
    view.dispatch({
      changes: { from, to, insert },
      selection: { anchor: from + view.state.toText(insert.slice(0, offset)).length },
      userEvent: "input.complete",
      scrollIntoView: true,
    })
  }
}

/** Removes the typed `/query`, then formats the line it was on. */
function lineCommand(apply: (view: EditorView) => unknown): SlashCommand["run"] {
  return (view, { from, to }) => {
    view.dispatch({ changes: { from, to }, selection: { anchor: from }, userEvent: "input.complete" })
    apply(view)
  }
}

type SlashLabels = Pick<
  MarkdownEditorLabels,
  | "paragraph"
  | "heading1"
  | "heading2"
  | "heading3"
  | "bulletList"
  | "orderedList"
  | "taskList"
  | "quote"
  | "codeBlock"
  | "table"
  | "divider"
>

const heading = (level: number) => lineCommand((view) => setHeading(view, level))
const lines = (format: MarkdownFormat) => lineCommand((view) => toggleFormat(view, format))

function markdownSlashCommands(labels: Partial<SlashLabels> = {}): SlashCommand[] {
  const text = { ...markdownEditorLabelsEn, ...labels }
  return [
    { value: "paragraph", label: text.paragraph, keywords: ["text"], run: heading(0) },
    { value: "h1", label: text.heading1, keywords: ["title"], hint: "#", run: heading(1) },
    { value: "h2", label: text.heading2, hint: "##", run: heading(2) },
    { value: "h3", label: text.heading3, hint: "###", run: heading(3) },
    { value: "bullet", label: text.bulletList, hint: "-", run: lines("bulletList") },
    { value: "ordered", label: text.orderedList, hint: "1.", run: lines("orderedList") },
    { value: "task", label: text.taskList, hint: "- [ ]", run: lines("taskList") },
    { value: "quote", label: text.quote, hint: ">", run: lines("quote") },
    { value: "code", label: text.codeBlock, hint: "```", run: insertBlock("```\n\n```", 4) },
    { value: "table", label: text.table, hint: "| |", run: insertBlock("|  |  |\n| --- | --- |\n|  |  |", 2) },
    { value: "divider", label: text.divider, hint: "---", run: insertBlock("---\n") },
  ]
}

type MarkdownEditorMenusProps = {
  adapter: TextEditorAdapter | undefined
  view: EditorView | undefined
  slashCommands: SlashCommand[]
  suggestWikilinks?: SuggestWikilinks
  onOpenChange: (open: boolean) => void
  emptyLabel: ReactNode
}

function MarkdownEditorMenus({
  adapter,
  view,
  slashCommands,
  suggestWikilinks,
  onOpenChange,
  emptyLabel,
}: MarkdownEditorMenusProps) {
  const triggers = useMemo<TriggerDefinition[]>(() => {
    const list: TriggerDefinition[] = [
      {
        char: "/",
        boundary: "word",
        type: "command",
        items: slashCommands.map(({ value, label, keywords }) => ({ value, label, keywords })),
      },
    ]
    if (suggestWikilinks) {
      list.push({
        char: "[[",
        boundary: "anywhere",
        spaces: true,
        maxLength: 80,
        pattern: /[^\]|[\r\n]/u,
        items: async (query, { signal }) =>
          (await suggestWikilinks(query, { signal })).map((item) => ({
            value: item.slug,
            label: item.label ?? item.slug,
          })),
        insert: (item) => wikilinkText(item.value),
      })
    }
    return list
  }, [slashCommands, suggestWikilinks])

  return (
    <TriggerMenu
      editor={adapter}
      triggers={triggers}
      onOpenChange={(open) => onOpenChange(open)}
      onSelect={(value, details) => {
        if (details.trigger !== "/" || !view) return
        const command = slashCommands.find((entry) => entry.value === value)
        if (!command) return
        details.preventDefault()
        command.run(view, { from: details.match.start, to: details.match.end })
      }}
    >
      <TriggerMenuContent
        side="bottom"
        align="start"
        sideOffset={4}
        className="max-h-(--available-height) w-64 overflow-y-auto surface-floating p-inline"
      >
        <TriggerMenuStatus className="sr-only" />
        <TriggerMenuEmpty className="px-inset-item py-inset-item text-sm text-muted-foreground not-data-empty:hidden">
          {emptyLabel}
        </TriggerMenuEmpty>
        <TriggerMenuList className="flex flex-col aria-busy:opacity-60">
          {(state) =>
            (state.items as TriggerMenuDataItem[]).map((item) => {
              const hint =
                state.trigger === "/"
                  ? slashCommands.find((entry) => entry.value === item.value)?.hint
                  : item.value !== item.label
                    ? item.value
                    : undefined
              return (
                <TriggerMenuItem
                  key={String(item.value)}
                  value={item.value}
                  label={item.label}
                  className="flex h-control-sm cursor-default items-center justify-between gap-inline rounded-control px-inset-item text-sm outline-none select-none data-disabled:opacity-50 data-highlighted:bg-accent data-highlighted:text-accent-foreground"
                >
                  <span className="truncate">{item.label}</span>
                  {hint && <span className="shrink-0 font-mono text-xs text-muted-foreground">{hint}</span>}
                </TriggerMenuItem>
              )
            })
          }
        </TriggerMenuList>
      </TriggerMenuContent>
    </TriggerMenu>
  )
}

export { MarkdownEditorMenus, markdownSlashCommands }
export type { SlashCommand, SlashLabels, SuggestWikilinks, WikilinkSuggestion }

"use client"

import { syntaxTree } from "@codemirror/language"
import type { EditorView } from "@codemirror/view"
import type { SyntaxNode } from "@lezer/common"
import { useState, useSyncExternalStore } from "react"
import { createPortal } from "react-dom"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import type { MarkdownEditorLabels } from "@/components/ui/markdown-editor-labels"
import type { PortalEntry, PortalStore } from "@/components/ui/markdown-editor-widgets"
import { MarkdownView, type MarkdownViewProps } from "@/components/ui/markdown-view"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { useRequestMeasure } from "@/components/ui/use-markdown-editor"

type ViewOptions = Pick<MarkdownViewProps, "resolveWikilink" | "taskLabel">

function fenceAt(view: EditorView, host: HTMLElement) {
  const pos = view.posAtDOM(host)
  for (let node: SyntaxNode | null = syntaxTree(view.state).resolveInner(pos, 1); node; node = node.parent) {
    if (node.name === "FencedCode") return node
  }
  return null
}

function setCodeInfo(view: EditorView, host: HTMLElement, info: string) {
  const fence = fenceAt(view, host)
  const open = fence?.firstChild
  if (!fence || open?.name !== "CodeMark" || view.state.readOnly) return
  const current = fence.getChild("CodeInfo")
  const from = current?.from ?? open.to
  view.dispatch({ changes: { from, to: current?.to ?? open.to, insert: info }, userEvent: "input.format" })
}

function CodeLanguage({
  entry,
  labels,
}: {
  entry: Extract<PortalEntry, { kind: "code-language" }>
  labels: MarkdownEditorLabels
}) {
  const [open, setOpen] = useState(false)
  const [draft, setDraft] = useState(entry.info)
  const readOnly = entry.view.state.readOnly
  const name = entry.info || labels.plainText
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next) setDraft(entry.info)
        setOpen(next)
      }}
    >
      <PopoverTrigger
        variant="ghost"
        disabled={readOnly}
        aria-label={`${labels.codeLanguage}: ${name}`}
        className="h-auto rounded-full px-inset-chip py-inset-chip text-caption text-muted-foreground"
      >
        {name}
      </PopoverTrigger>
      <PopoverContent side="bottom" align="start" finalFocus={() => entry.view.contentDOM} className="w-64 p-inline">
        <form
          className="flex items-center gap-inline"
          onSubmit={(event) => {
            event.preventDefault()
            setCodeInfo(entry.view, entry.host, draft.trim())
            setOpen(false)
          }}
        >
          <Input aria-label={labels.codeLanguage} value={draft} onValueChange={setDraft} className="h-control-sm" />
          <Button type="submit" size="sm">
            {labels.apply}
          </Button>
        </form>
      </PopoverContent>
    </Popover>
  )
}

function TableBlock({ entry, options }: { entry: Extract<PortalEntry, { kind: "table" }>; options: ViewOptions }) {
  useRequestMeasure(entry.view)
  return (
    <div className="cursor-text overflow-x-auto">
      <MarkdownView markdown={entry.source} sourcePositions {...options} />
    </div>
  )
}

const keys = new WeakMap<HTMLElement, number>()
let nextKey = 0
const keyOf = (host: HTMLElement) => {
  let key = keys.get(host)
  if (key === undefined) keys.set(host, (key = nextKey++))
  return key
}

function MarkdownEditorPortals({
  store,
  labels,
  options,
}: {
  store: PortalStore
  labels: MarkdownEditorLabels
  options: ViewOptions
}) {
  const entries = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
  return entries.map((entry) =>
    createPortal(
      entry.kind === "table" ? (
        <TableBlock entry={entry} options={options} />
      ) : (
        <CodeLanguage entry={entry} labels={labels} />
      ),
      entry.host,
      String(keyOf(entry.host)),
    ),
  )
}

export { MarkdownEditorPortals }

import { syntaxTree } from "@codemirror/language"
import { Facet, StateEffect, type EditorState, type Range } from "@codemirror/state"
import {
  Decoration,
  EditorView,
  ViewPlugin,
  type DecorationSet,
  type PluginValue,
  type ViewUpdate,
} from "@codemirror/view"

import { decorateTree, hidden, line, slot } from "@/components/ui/markdown-editor-inline"
import { blockMarks, lineStructure, type Span } from "@/components/ui/markdown-editor-structure"
import { BulletWidget, TaskWidget, type PortalStore } from "@/components/ui/markdown-editor-widgets"
import type { WikilinkResolver } from "@/components/ui/markdown-syntax"

type PreviewConfig = { resolve?: WikilinkResolver; taskLabel: string; portals?: PortalStore }

const previewConfig = Facet.define<PreviewConfig, PreviewConfig>({
  combine: (values) => values[0] ?? { taskLabel: "Task done" },
})

const refreshReveal = StateEffect.define<null>()
const bullet = Decoration.replace({ widget: new BulletWidget() })

function selectionSpans(state: EditorState): Span[] {
  if (state.readOnly) return []
  return state.selection.ranges.map((range) => ({ from: range.from, to: range.to }))
}

function decorateLines(state: EditorState, from: number, to: number, config: PreviewConfig) {
  const ranges: Range<Decoration>[] = []
  const atomic: Range<Decoration>[] = []
  const marks = blockMarks(state, from, to)
  for (let pos = from; pos <= to;) {
    const current = state.doc.lineAt(pos)
    pos = current.to + 1
    const structure = lineStructure(state, current, marks)
    const attributes: Record<string, string> = {}
    if (structure.depth) attributes["data-md-depth"] = String(Math.min(structure.depth, 8))
    if (structure.bullet || structure.ordered || structure.task) attributes["data-md-item"] = ""
    if (structure.quote) attributes["data-md-quote"] = String(Math.min(structure.quote, 4))
    if (Object.keys(attributes).length) ranges.push(line(attributes).range(current.from))
    for (const span of structure.hidden) if (span.to > span.from) ranges.push(hidden.range(span.from, span.to))
    if (structure.bullet) {
      const decoration = structure.task ? hidden : bullet
      ranges.push(decoration.range(structure.bullet.from, structure.bullet.to))
    }
    if (structure.ordered) ranges.push(slot("markdown-list-number").range(structure.ordered.from, structure.ordered.to))
    const { task } = structure
    if (task) {
      const widget = new TaskWidget(task.checked, config.taskLabel)
      ranges.push(Decoration.replace({ widget }).range(task.from, task.to))
      if (task.from >= structure.hiddenEnd) atomic.push(hidden.range(task.from, task.to))
    }
    if (structure.hiddenEnd > current.from) atomic.push(hidden.range(current.from, structure.hiddenEnd))
  }
  return { ranges, atomic }
}

class Preview implements PluginValue {
  decorations: DecorationSet = Decoration.none
  atomic: DecorationSet = Decoration.none
  private reveal: Span[]
  private measuring = false

  constructor(readonly view: EditorView) {
    this.reveal = selectionSpans(view.state)
    this.build()
  }

  update(update: ViewUpdate) {
    const refresh = update.transactions.some((tr) => tr.effects.some((effect) => effect.is(refreshReveal)))
    const configChanged = update.startState.facet(previewConfig) !== update.state.facet(previewConfig)
    // While an IME composes, the decorations around the caret must stay put or the composition breaks.
    if (update.view.composing && !refresh) {
      this.reveal = this.reveal.map((span) => ({
        from: update.changes.mapPos(span.from, -1),
        to: update.changes.mapPos(span.to, 1),
      }))
    } else if (update.selectionSet || update.docChanged || configChanged || refresh) {
      this.reveal = selectionSpans(update.state)
    }
    if (
      update.docChanged ||
      update.viewportChanged ||
      update.selectionSet ||
      refresh ||
      configChanged ||
      syntaxTree(update.startState) !== syntaxTree(update.state)
    ) {
      this.build()
    }
  }

  private build() {
    const { view } = this
    const { state } = view
    const config = state.facet(previewConfig)
    const ranges: Range<Decoration>[] = []
    const atomic: Range<Decoration>[] = []
    const reveal = this.reveal
    const revealed = (from: number, to: number) => reveal.some((span) => span.from <= to && span.to >= from)
    for (const { from, to } of view.visibleRanges) {
      const lines = decorateLines(state, from, to, config)
      ranges.push(...lines.ranges)
      atomic.push(...lines.atomic)
      decorateTree({ state, ranges, revealed, resolve: config.resolve, portals: config.portals }, from, to)
    }
    this.decorations = Decoration.set(ranges, true)
    this.atomic = Decoration.set(atomic, true)
    if (!this.measuring && ranges.some((range) => range.value.spec.attributes?.["data-md-table-id"])) {
      this.measuring = true
      view.requestMeasure({ key: this, read: () => this.readColumns(), write: (widths) => this.alignColumns(widths) })
    }
  }

  // Columns line up by giving every cell its column's widest text, measured from the text itself so the min-width
  // never feeds back; it's set through the CSSOM because a style attribute is blocked under a strict CSP.
  private readColumns() {
    this.measuring = false
    const cells = [...this.view.contentDOM.querySelectorAll<HTMLElement>("[data-md-table-id]")]
    const widths = new Map<string, number>()
    const range = document.createRange()
    for (const cell of cells) {
      range.selectNodeContents(cell)
      const key = `${cell.dataset.mdTableId}:${cell.dataset.mdColumn}`
      widths.set(key, Math.max(widths.get(key) ?? 0, range.getBoundingClientRect().width))
    }
    return { cells, widths }
  }

  private alignColumns({ cells, widths }: ReturnType<Preview["readColumns"]>) {
    for (const cell of cells) {
      const width = widths.get(`${cell.dataset.mdTableId}:${cell.dataset.mdColumn}`) ?? 0
      cell.style.minWidth = width ? `${Math.ceil(width)}px` : ""
    }
  }
}

const livePreview = ViewPlugin.fromClass(Preview, {
  decorations: (plugin) => plugin.decorations,
  provide: (plugin) => EditorView.atomicRanges.of((view) => view.plugin(plugin)?.atomic ?? Decoration.none),
  eventHandlers: {
    mousedown(event, view) {
      const target = event.target
      if (!(target instanceof HTMLInputElement) || target.dataset.slot !== "markdown-task") return false
      if (view.state.readOnly) return true
      return toggleTaskAt(view, view.posAtDOM(target))
    },
    compositionend(_event, view) {
      setTimeout(() => view.dom.isConnected && view.dispatch({ effects: refreshReveal.of(null) }))
    },
  },
})

function toggleTaskAt(view: EditorView, pos: number) {
  const text = view.state.doc.sliceString(pos, pos + 3)
  const match = /^\[([ xX])\]$/.exec(text)
  if (!match) return false
  view.dispatch({
    changes: { from: pos + 1, to: pos + 2, insert: match[1] === " " ? "x" : " " },
    userEvent: "input.toggle",
  })
  return true
}

export { livePreview, previewConfig, toggleTaskAt }
export type { PreviewConfig }

import { definePrimitive } from "@ui-sdk/core"

import type { MarkdownFormat } from "@/components/ui/markdown-editor-commands"

type MarkdownEditorHandle = {
  getMarkdown: () => string
  insertText: (text: string) => boolean
  replaceSelection: (text: string) => boolean
  insertWikilink: (slug: string, label?: string) => boolean
  toggleFormat: (format: MarkdownFormat) => boolean
  setHeading: (level: number) => boolean
  toggleTask: (line: number) => boolean
  setMarkdown: (markdown: string) => boolean
}

type MarkdownEditorOptions = { editor?: MarkdownEditorHandle; readOnly?: boolean }

function handleOf(options: () => MarkdownEditorOptions, write: boolean) {
  const { editor, readOnly } = options()
  if (!editor) throw new Error("The editor isn't ready yet.")
  if (write && readOnly) throw new Error("This document is read-only.")
  return editor
}

const stateOf = (options: MarkdownEditorOptions) => ({ readOnly: Boolean(options.readOnly) })

const markdownEditor = definePrimitive({
  name: "markdown-editor",
  options: { editor: "value", readOnly: "boolean" },
  state: stateOf,
  sync: stateOf,
  api: (context) => ({
    getMarkdown: () => handleOf(context.options, false).getMarkdown(),
    insertText: (text: string) => handleOf(context.options, true).insertText(String(text)),
    replaceSelection: (text: string) => handleOf(context.options, true).replaceSelection(String(text)),
    insertWikilink: (slug: string, label?: string) =>
      handleOf(context.options, true).insertWikilink(String(slug), label === undefined ? undefined : String(label)),
    toggleFormat: (format: MarkdownFormat) => handleOf(context.options, true).toggleFormat(format),
    setHeading: (level: number) => handleOf(context.options, true).setHeading(Number(level)),
    toggleTask: (line: number) => handleOf(context.options, true).toggleTask(Number(line)),
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-readonly": state.readOnly ? "" : undefined }),
    }),
  }),
  agent: {
    actions: [
      "getMarkdown",
      "insertText",
      "replaceSelection",
      "insertWikilink",
      "toggleFormat",
      "setHeading",
      "toggleTask",
    ],
  },
})

type MarkdownDocumentOptions = MarkdownEditorOptions & { agentConfirm?: string }

const documentStateOf = (options: MarkdownDocumentOptions) => ({
  readOnly: Boolean(options.readOnly),
  agentConfirm: options.agentConfirm,
})

// A separate component so its confirm mark covers only the whole-document replacement, not the editor's other actions.
const markdownDocument = definePrimitive({
  name: "markdown-document",
  options: { editor: "value", readOnly: "boolean", agentConfirm: "string" },
  state: documentStateOf,
  sync: documentStateOf,
  api: (context) => ({
    setMarkdown: (markdown: string) => handleOf(context.options, true).setMarkdown(String(markdown)),
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-agent-confirm": state.agentConfirm }),
    }),
  }),
  agent: { actions: ["setMarkdown"], shown: (state) => !state.readOnly },
})

export { markdownDocument, markdownEditor }
export type { MarkdownEditorHandle, MarkdownEditorOptions }

import { defaultKeymap, history, historyKeymap } from "@codemirror/commands"
import { commonmarkLanguage, markdownKeymap } from "@codemirror/lang-markdown"
import {
  Language,
  LanguageDescription,
  LanguageSupport,
  ParseContext,
  syntaxHighlighting,
  syntaxTree,
} from "@codemirror/language"
import { parseCode, type MarkdownParser } from "@lezer/markdown"
import { Annotation, Compartment, EditorState, type Extension } from "@codemirror/state"
import { EditorView, placeholder as placeholderText, type KeyBinding, type ViewUpdate } from "@codemirror/view"
import { classHighlighter } from "@lezer/highlight"

import { menuAwareKeymap } from "@/components/ui/markdown-editor-adapter"
import { blockPreview } from "@/components/ui/markdown-editor-blocks"
import { lineSeparatorExtension, toggleFormat } from "@/components/ui/markdown-editor-commands"
import { deleteMarker, indentList, outdentList, setHeading } from "@/components/ui/markdown-editor-lines"
import { livePreview, previewConfig, toggleTaskAt, type PreviewConfig } from "@/components/ui/markdown-editor-preview"
import { caretOutOfPrefix } from "@/components/ui/markdown-editor-structure"
import { markdownEditorTheme } from "@/components/ui/markdown-editor-theme"
import { markdownExtensions } from "@/components/ui/markdown-syntax"

/** Marks a transaction that came from `value`, so it never echoes back through `onChange`. */
const fromValue = Annotation.define<boolean>()

type CodeLanguages = readonly LanguageDescription[]
type EditorSettings = {
  label: string
  describedBy?: string
  readOnly: boolean
  placeholder?: string
  cspNonce?: string
  preview: PreviewConfig
}
type EditorHooks = {
  bridge: Extension
  onUpdate: (update: ViewUpdate) => void
  openWikilink: (slug: string) => void
}

const supports = new WeakMap<CodeLanguages, LanguageSupport>()
const NO_LANGUAGES: CodeLanguages = []

// `markdown()` always builds an HTML language for inline tags, which pulls lang-html, lang-css and
// lang-javascript into the bundle; HTML here is shown as muted text, so the language is built directly.
function markdownSupport(languages: CodeLanguages) {
  let support = supports.get(languages)
  if (support) return support
  const codeParser = (info: string) => {
    const found = LanguageDescription.matchLanguageName(languages, info, true)
    if (!found) return null
    return found.support ? found.support.language.parser : ParseContext.getSkippingParser(found.load())
  }
  const parser = (commonmarkLanguage.parser as MarkdownParser).configure([
    ...markdownExtensions,
    parseCode({ codeParser }),
  ])
  support = new LanguageSupport(new Language(commonmarkLanguage.data, parser, [], "markdown"))
  supports.set(languages, support)
  return support
}

const readOnlySlot = new Compartment()
const attributesSlot = new Compartment()
const previewSlot = new Compartment()
const placeholderSlot = new Compartment()
const nonceSlot = new Compartment()

const readOnlyExtension = (readOnly: boolean) => EditorState.readOnly.of(readOnly)
const attributesExtension = ({ label, describedBy, readOnly }: EditorSettings) =>
  EditorView.contentAttributes.of({
    role: "textbox",
    "aria-multiline": "true",
    "aria-label": label,
    ...(describedBy ? { "aria-describedby": describedBy } : {}),
    ...(readOnly ? { "aria-readonly": "true" } : {}),
  })
const nonceExtension = (nonce?: string) => (nonce ? EditorView.cspNonce.of(nonce) : [])
const placeholderExtension = (text?: string) => (text ? placeholderText(text) : [])

function wikilinkAt(state: EditorState, pos: number) {
  for (const side of [1, -1] as const) {
    for (
      let node: ReturnType<typeof syntaxTree>["topNode"] | null = syntaxTree(state).resolveInner(pos, side);
      node;
      node = node.parent
    ) {
      if (node.name !== "Wikilink") continue
      const target = node.getChild("WikilinkTarget")
      if (target) return { slug: state.sliceDoc(target.from, target.to).trim(), from: node.from, to: node.to }
    }
  }
  return null
}

const TASK_PREFIX = /^(\s*(?:[-*+]|\d+[.)])\s+)\[[ xX]\]/

function toggleTaskOnLine(view: EditorView, number: number) {
  if (view.state.readOnly || number < 1 || number > view.state.doc.lines) return false
  const line = view.state.doc.line(number)
  const prefix = TASK_PREFIX.exec(line.text)?.[1]
  return prefix !== undefined && toggleTaskAt(view, line.from + prefix.length)
}

function editorKeymap(hooks: EditorHooks): KeyBinding[] {
  return [
    {
      key: "Enter",
      run: (view) => {
        const { main } = view.state.selection
        const link = main.empty ? wikilinkAt(view.state, main.head) : null
        if (!link || main.head <= link.from || main.head >= link.to) return false
        hooks.openWikilink(link.slug)
        return true
      },
    },
    {
      key: "Mod-Enter",
      run: (view) => toggleTaskOnLine(view, view.state.doc.lineAt(view.state.selection.main.head).number),
    },
    { key: "Tab", run: indentList },
    { key: "Shift-Tab", run: outdentList },
    { key: "Backspace", run: deleteMarker },
    ...[0, 1, 2, 3, 4, 5, 6].map((level) => ({
      key: `Mod-Alt-${level}`,
      run: (view: EditorView) => setHeading(view, level),
    })),
    { key: "Mod-b", run: (view) => toggleFormat(view, "bold") },
    { key: "Mod-i", run: (view) => toggleFormat(view, "italic") },
    { key: "Mod-e", run: (view) => toggleFormat(view, "code") },
    { key: "Mod-Shift-x", run: (view) => toggleFormat(view, "strikethrough") },
    ...markdownKeymap,
    ...historyKeymap,
    ...defaultKeymap,
  ]
}

function createEditorState(doc: string, settings: EditorSettings, hooks: EditorHooks, languages = NO_LANGUAGES) {
  return EditorState.create({
    doc,
    extensions: [
      lineSeparatorExtension(doc),
      history(),
      markdownSupport(languages),
      syntaxHighlighting(classHighlighter),
      EditorView.lineWrapping,
      markdownEditorTheme,
      menuAwareKeymap(editorKeymap(hooks)),
      livePreview,
      blockPreview,
      caretOutOfPrefix,
      nonceSlot.of(nonceExtension(settings.cspNonce)),
      readOnlySlot.of(readOnlyExtension(settings.readOnly)),
      attributesSlot.of(attributesExtension(settings)),
      previewSlot.of(previewConfig.of(settings.preview)),
      placeholderSlot.of(placeholderExtension(settings.placeholder)),
      EditorView.domEventHandlers({
        mousedown(event, view) {
          if (!(event.metaKey || event.ctrlKey) || event.button !== 0) return false
          const pos = view.posAtCoords({ x: event.clientX, y: event.clientY })
          const link = pos === null ? null : wikilinkAt(view.state, pos)
          if (!link) return false
          hooks.openWikilink(link.slug)
          return true
        },
      }),
      EditorView.updateListener.of(hooks.onUpdate),
      hooks.bridge,
    ],
  })
}

function reconfigure(view: EditorView, settings: EditorSettings) {
  view.dispatch({
    effects: [
      readOnlySlot.reconfigure(readOnlyExtension(settings.readOnly)),
      attributesSlot.reconfigure(attributesExtension(settings)),
      previewSlot.reconfigure(previewConfig.of(settings.preview)),
      placeholderSlot.reconfigure(placeholderExtension(settings.placeholder)),
      nonceSlot.reconfigure(nonceExtension(settings.cspNonce)),
    ],
  })
}

export { createEditorState, fromValue, reconfigure, toggleTaskOnLine, wikilinkAt }
export type { CodeLanguages, EditorHooks, EditorSettings }

import { syntaxTree } from "@codemirror/language"
import { EditorSelection, EditorState, type Line, type Transaction } from "@codemirror/state"
import type { SyntaxNode } from "@lezer/common"

type Span = { from: number; to: number }

/** The block syntax at the start of a line, which the preview never shows as text. */
type LineStructure = {
  /** Ranges hidden outright: indentation, `>` marks and a heading's `#`s. */
  hidden: Span[]
  /** End of the hidden run that starts the line; the caret never rests inside it. */
  hiddenEnd: number
  /** Where the line's text starts, after every marker. */
  contentStart: number
  depth: number
  quote: number
  heading?: number
  bullet?: Span
  ordered?: Span
  task?: Span & { checked: boolean }
  listItem?: SyntaxNode
  continuation?: boolean
}

const MARKS = new Set(["QuoteMark", "ListMark", "TaskMarker", "HeaderMark"])
const isSpace = (char: string | undefined) => char === " " || char === "\t"

function listDepth(node: SyntaxNode | null) {
  let depth = 0
  for (let at = node; at; at = at.parent) if (at.name === "ListItem") depth++
  return depth
}

// Block marks sit in these nodes; inline content never holds one, so the walk skips it.
const HOLDERS = /^(Document|Blockquote|BulletList|OrderedList|ListItem|Task|Paragraph|FencedCode|ATXHeading\d)$/

/** Every block mark that starts between `from` and `to`, by position, in one walk of the tree. */
function blockMarks(state: EditorState, from: number, to: number) {
  const marks = new Map<number, SyntaxNode>()
  syntaxTree(state).iterate({
    from,
    to,
    enter(ref) {
      if (MARKS.has(ref.name)) {
        if (ref.from >= from) marks.set(ref.from, ref.node)
        return false
      }
      return HOLDERS.test(ref.name) ? undefined : false
    },
  })
  return marks
}

function lineStructure(state: EditorState, line: Line, marks = blockMarks(state, line.from, line.to)): LineStructure {
  const result: LineStructure = { hidden: [], hiddenEnd: line.from, contentStart: line.from, depth: 0, quote: 0 }
  const text = line.text
  const charAt = (pos: number) => text[pos - line.from]
  const spacesFrom = (pos: number) => {
    while (pos < line.to && isSpace(charAt(pos))) pos++
    return pos
  }
  let pos = line.from
  let hiddenEnd: number | undefined
  for (;;) {
    const start = spacesFrom(pos)
    const mark = marks.get(start)
    if (!mark) break
    if (mark.name === "QuoteMark") {
      const end = isSpace(charAt(mark.to)) ? mark.to + 1 : mark.to
      result.hidden.push({ from: pos, to: end })
      result.quote++
      pos = end
    } else if (mark.name === "ListMark") {
      const end = Math.min(spacesFrom(mark.to), mark.to + 4)
      if (start > pos) result.hidden.push({ from: pos, to: start })
      result.listItem = mark.parent ?? undefined
      result.depth = listDepth(mark)
      if (mark.parent?.parent?.name === "OrderedList") {
        result.ordered = { from: mark.from, to: mark.to }
        hiddenEnd ??= start
      } else {
        result.bullet = { from: mark.from, to: end }
      }
      pos = end
    } else if (mark.name === "TaskMarker") {
      const checked = /x/i.test(state.sliceDoc(mark.from + 1, mark.to - 1))
      result.task = { from: mark.from, to: mark.to, checked }
      pos = isSpace(charAt(mark.to)) ? mark.to + 1 : mark.to
      if (pos > mark.to) result.hidden.push({ from: mark.to, to: pos })
    } else if (mark.name === "HeaderMark" && mark.parent?.name.startsWith("ATX") && !mark.prevSibling) {
      const end = spacesFrom(mark.to)
      result.hidden.push({ from: pos, to: end })
      result.heading = Number(mark.parent.name.slice(-1))
      pos = end
      break
    } else {
      break
    }
  }
  if (pos === line.from && isSpace(text[0])) {
    const start = spacesFrom(pos)
    const inner = syntaxTree(state).resolveInner(start, 1)
    const depth = listDepth(inner)
    if (depth > 0 && (inner.name === "Paragraph" || inner.name === "Task") && start < line.to) {
      result.hidden.push({ from: line.from, to: start })
      result.depth = depth
      result.continuation = true
      pos = start
    }
  }
  result.contentStart = pos
  result.hiddenEnd = hiddenEnd ?? pos
  return result
}

/**
 * Keeps an empty caret out of a line's hidden prefix, so typing lands in the text. Moving left from the text's
 * start goes on to the previous line instead of stopping at the hidden marks.
 */
const caretOutOfPrefix = EditorState.transactionFilter.of((transaction: Transaction) => {
  const selection = transaction.selection
  if (!selection || selection.ranges.length !== 1 || !selection.main.empty) return transaction
  const state = transaction.state
  const head = selection.main.head
  const line = state.doc.lineAt(head)
  if (head - line.from > 64) return transaction
  const structure = lineStructure(state, line)
  if (structure.hiddenEnd === line.from || head >= structure.hiddenEnd) return transaction
  const previous = transaction.startState.selection.main
  const movingBack = previous.empty && transaction.changes.mapPos(previous.head) === structure.hiddenEnd
  const target = movingBack && line.number > 1 ? line.from - 1 : structure.hiddenEnd
  return [transaction, { selection: EditorSelection.cursor(target), sequential: true }]
})

export { blockMarks, caretOutOfPrefix, lineStructure, listDepth }
export type { LineStructure, Span }

import { Transaction, type EditorState, type Text } from "@codemirror/state"
import type { EditorView, ViewUpdate } from "@codemirror/view"
import { useState, type RefObject } from "react"

import { replaceDocument } from "@/components/ui/markdown-editor-commands"
import { fromValue } from "@/components/ui/markdown-editor-state"

type MarkdownConflict = { local: string; remote: string }

type SyncProps = {
  onChange?: (markdown: string) => void
  onDirtyChange?: (dirty: boolean) => void
  onConflict?: (conflict: MarkdownConflict) => string | undefined | void
  changeDelay?: number
}

const noop = () => {}

/** Keeps the editor and the `value` prop in step: debounced `onChange`, dirty state and outside updates. */
function createSync(props: RefObject<SyncProps>) {
  let view: EditorView | undefined
  let rebuildState: (markdown: string) => void = noop
  let baseline: Text | undefined
  let emitted: string | undefined
  let dirty = false
  let timer: ReturnType<typeof setTimeout> | undefined

  const updateDirty = (state: EditorState) => {
    const next = baseline ? !state.doc.eq(baseline) : false
    if (next === dirty) return
    dirty = next
    props.current.onDirtyChange?.(next)
  }
  const emit = (markdown: string) => {
    emitted = markdown
    props.current.onChange?.(markdown)
  }
  const flush = () => {
    if (timer === undefined || !view) return
    clearTimeout(timer)
    timer = undefined
    emit(view.state.sliceDoc())
  }
  const schedule = () => {
    if (timer !== undefined) clearTimeout(timer)
    timer = setTimeout(flush, props.current.changeDelay ?? 300)
  }
  const apply = (markdown: string) => {
    if (!view) return
    if (!replaceDocument(view, markdown, [fromValue.of(true), Transaction.addToHistory.of(false)]))
      rebuildState(markdown)
  }

  return {
    attach(editor: EditorView, initial: string, rebuild: (markdown: string) => void) {
      view = editor
      rebuildState = rebuild
      baseline = editor.state.doc
      emitted = initial
      return () => {
        flush()
        view = undefined
      }
    },
    onUpdate(update: ViewUpdate) {
      if (update.focusChanged && !update.view.hasFocus) flush()
      if (!update.docChanged) return
      updateDirty(update.state)
      if (update.transactions.some((transaction) => transaction.annotation(fromValue))) return
      schedule()
    },
    receive(value: string) {
      if (!view) return
      if (value !== emitted && value !== view.state.sliceDoc()) {
        if (timer === undefined) apply(value)
        else {
          clearTimeout(timer)
          timer = undefined
          const local = view.state.sliceDoc()
          const { onConflict } = props.current
          if (onConflict) {
            const kept = onConflict({ local, remote: value })
            apply(typeof kept === "string" ? kept : value)
            if (typeof kept === "string" && kept !== value) schedule()
          } else {
            emit(local)
            apply(value)
          }
        }
      }
      emitted = value
      baseline = view.state.toText(value)
      updateDirty(view.state)
    },
    rebuild: (markdown: string) => rebuildState(markdown),
  }
}

function useMarkdownSync(props: RefObject<SyncProps>) {
  const [sync] = useState(() => createSync(props))
  return sync
}

export { useMarkdownSync }
export type { MarkdownConflict }

"use client"

import { MenuTrigger } from "@ui-sdk/react/menu"
import { Toolbar, ToolbarButton, ToolbarSeparator } from "@ui-sdk/react/toolbar"
import { useRef, useState, type ReactNode } from "react"
import {
  BoldIcon,
  ChevronDownIcon,
  CodeIcon,
  EllipsisIcon,
  HeadingIcon,
  ItalicIcon,
  LinkIcon,
  ListIcon,
  ListOrderedIcon,
  ListTodoIcon,
  StrikethroughIcon,
  TextQuoteIcon,
} from "lucide-react"

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuItemIcon,
  DropdownMenuItemIndicator,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
} from "@/components/ui/dropdown-menu"
import type { MarkdownFormat } from "@/components/ui/markdown-editor-commands"
import type { MarkdownEditorLabels } from "@/components/ui/markdown-editor-labels"
import { ControlTooltip } from "@/components/ui/tooltip"
import { useResizeObserver } from "@/components/ui/use-markdown-editor"

type ToolbarFormat = Exclude<MarkdownFormat, "heading">

// The keys mirror the editor's keymap (markdown-editor-state.ts), so the tooltip shows what the button is bound to.
const ITEMS: { format: ToolbarFormat; glyph: ReactNode; group: number; shortcut?: string }[] = [
  { group: 0, format: "bold", glyph: <BoldIcon />, shortcut: "mod+b" },
  { group: 0, format: "italic", glyph: <ItalicIcon />, shortcut: "mod+i" },
  { group: 0, format: "strikethrough", glyph: <StrikethroughIcon />, shortcut: "mod+shift+x" },
  { group: 0, format: "code", glyph: <CodeIcon />, shortcut: "mod+e" },
  { group: 0, format: "link", glyph: <LinkIcon /> },
  { group: 1, format: "quote", glyph: <TextQuoteIcon /> },
  { group: 1, format: "bulletList", glyph: <ListIcon /> },
  { group: 1, format: "orderedList", glyph: <ListOrderedIcon /> },
  { group: 1, format: "taskList", glyph: <ListTodoIcon /> },
]

const LEVELS = [0, 1, 2, 3, 4, 5, 6] as const
const levelLabel = (labels: MarkdownEditorLabels, level: number) =>
  level === 0 ? labels.paragraph : labels[`heading${level}` as `heading${1 | 2 | 3 | 4 | 5 | 6}`]

const buttonClassName =
  "touch-target inline-flex size-control-sm shrink-0 items-center justify-center rounded-control text-muted-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring data-disabled:opacity-50 data-open:bg-accent data-open:text-accent-foreground [&_svg]:size-4"

/** How many items fit beside the heading menu, leaving room for the "more" button when some don't. */
function fitCount(toolbar: HTMLElement) {
  const style = getComputedStyle(toolbar)
  const gap = Number.parseFloat(style.columnGap) || 0
  const available =
    toolbar.clientWidth - Number.parseFloat(style.paddingInlineStart) - Number.parseFloat(style.paddingInlineEnd)
  const button = toolbar.querySelector("[data-slot=toolbar-button]")
  if (!available || !button) return ITEMS.length
  const item = button.getBoundingClientRect().width + gap
  const separator = (toolbar.querySelector("[data-slot=toolbar-separator]")?.getBoundingClientRect().width ?? 1) + gap
  let used = item + separator
  const widths = ITEMS.map(
    (entry, index) => item + (index > 0 && entry.group !== ITEMS[index - 1]!.group ? separator : 0),
  )
  if (used + widths.reduce((sum, width) => sum + width, 0) <= available) return ITEMS.length
  let count = 0
  for (const width of widths) {
    if (used + width + item > available) break
    used += width
    count++
  }
  return count
}

const keepSelection = (event: { preventDefault: () => void }) => event.preventDefault()

type MarkdownEditorToolbarProps = {
  labels: MarkdownEditorLabels
  onFormat: (format: ToolbarFormat) => void
  onHeading: (level: number) => void
  headingLevel: () => number
  restoreFocus: () => HTMLElement | null
}

function MarkdownEditorToolbar({
  labels,
  onFormat,
  onHeading,
  headingLevel,
  restoreFocus,
}: MarkdownEditorToolbarProps) {
  const ref = useRef<HTMLDivElement>(null)
  const [visible, setVisible] = useState(ITEMS.length)
  const [level, setLevel] = useState(0)

  useResizeObserver(ref, (toolbar) => setVisible(fitCount(toolbar)))

  const shown = ITEMS.slice(0, visible)
  const overflow = ITEMS.slice(visible)

  return (
    <Toolbar
      ref={ref}
      aria-label={labels.toolbar}
      className="flex min-w-0 flex-nowrap items-center gap-inline overflow-hidden border-b px-inset-item py-inline"
    >
      <DropdownMenu
        onOpenChange={(open) => open && setLevel(headingLevel())}
        onValueChange={(value) => onHeading(Number(value))}
      >
        <ControlTooltip label={labels.blockType}>
          <ToolbarButton
            render={<MenuTrigger />}
            aria-label={labels.blockType}
            onMouseDown={keepSelection}
            className={`${buttonClassName} w-auto gap-inline px-inline`}
          >
            <HeadingIcon />
            <ChevronDownIcon />
          </ToolbarButton>
        </ControlTooltip>
        <DropdownMenuContent finalFocus={restoreFocus}>
          <DropdownMenuRadioGroup value={String(level)} aria-label={labels.blockType}>
            {LEVELS.map((value) => (
              <DropdownMenuRadioItem key={value} value={String(value)}>
                <DropdownMenuItemIndicator />
                {levelLabel(labels, value)}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuContent>
      </DropdownMenu>
      <ToolbarSeparator className="h-5 w-px shrink-0 self-center bg-border" />
      {shown.map(({ format, glyph, group, shortcut }, index) => [
        index > 0 && group !== shown[index - 1]!.group && (
          <ToolbarSeparator key={`separator-${format}`} className="h-5 w-px shrink-0 self-center bg-border" />
        ),
        <ControlTooltip key={format} label={labels[format]} shortcut={shortcut}>
          <ToolbarButton
            aria-label={labels[format]}
            // Keeps focus and the selection in the editor; the toolbar still takes focus from the keyboard.
            onMouseDown={keepSelection}
            onClick={() => onFormat(format)}
            className={buttonClassName}
          >
            {glyph}
          </ToolbarButton>
        </ControlTooltip>,
      ])}
      {overflow.length > 0 && (
        <DropdownMenu onAction={(value) => onFormat(value as ToolbarFormat)}>
          <ControlTooltip label={labels.more}>
            <ToolbarButton
              render={<MenuTrigger />}
              aria-label={labels.more}
              onMouseDown={keepSelection}
              className={`${buttonClassName} ms-auto`}
            >
              <EllipsisIcon />
            </ToolbarButton>
          </ControlTooltip>
          <DropdownMenuContent align="end" finalFocus={restoreFocus}>
            {overflow.map(({ format, glyph }) => (
              <DropdownMenuItem key={format} value={format}>
                <DropdownMenuItemIcon>{glyph}</DropdownMenuItemIcon>
                {labels[format]}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </Toolbar>
  )
}

export { MarkdownEditorToolbar }
export type { ToolbarFormat }

import { WidgetType, type EditorView } from "@codemirror/view"

type PortalEntry =
  | { kind: "code-language"; host: HTMLElement; view: EditorView; info: string }
  | { kind: "table"; host: HTMLElement; view: EditorView; source: string }

/** Widgets whose content React renders through portals, so their controls are UI SDK parts. */
class PortalStore {
  private entries = new Map<HTMLElement, PortalEntry>()
  private listeners = new Set<() => void>()
  private snapshot: PortalEntry[] = []

  readonly subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }
  readonly getSnapshot = () => this.snapshot

  set(entry: PortalEntry) {
    this.entries.set(entry.host, entry)
    this.changed()
  }
  delete(host: HTMLElement) {
    if (this.entries.delete(host)) this.changed()
  }
  private changed() {
    this.snapshot = [...this.entries.values()]
    for (const listener of this.listeners) listener()
  }
}

class BulletWidget extends WidgetType {
  override eq() {
    return true
  }
  toDOM() {
    const span = document.createElement("span")
    span.dataset.slot = "markdown-bullet"
    span.setAttribute("aria-hidden", "true")
    return span
  }
  override ignoreEvent() {
    return false
  }
}

class TaskWidget extends WidgetType {
  constructor(
    readonly checked: boolean,
    readonly label: string,
  ) {
    super()
  }
  override eq(other: TaskWidget) {
    return other.checked === this.checked && other.label === this.label
  }
  toDOM() {
    const box = document.createElement("input")
    box.type = "checkbox"
    box.checked = this.checked
    box.dataset.slot = "markdown-task"
    box.setAttribute("aria-label", this.label)
    return box
  }
  override ignoreEvent() {
    return false
  }
}

class LabelWidget extends WidgetType {
  constructor(readonly text: string) {
    super()
  }
  override eq(other: LabelWidget) {
    return other.text === this.text
  }
  toDOM() {
    const span = document.createElement("span")
    span.textContent = this.text
    return span
  }
  override ignoreEvent() {
    return false
  }
}

class CodeLanguageWidget extends WidgetType {
  constructor(
    readonly info: string,
    readonly store: PortalStore,
  ) {
    super()
  }
  override eq(other: CodeLanguageWidget) {
    return other.info === this.info && other.store === this.store
  }
  toDOM(view: EditorView) {
    const host = document.createElement("span")
    host.dataset.slot = "markdown-code-language"
    host.contentEditable = "false"
    this.store.set({ kind: "code-language", host, view, info: this.info })
    return host
  }
  override destroy(dom: HTMLElement) {
    this.store.delete(dom)
  }
}

class TableWidget extends WidgetType {
  constructor(
    readonly source: string,
    readonly store: PortalStore,
    readonly rows: number,
  ) {
    super()
  }
  override eq(other: TableWidget) {
    return other.source === this.source && other.store === this.store
  }
  override get estimatedHeight() {
    return this.rows * 36
  }
  toDOM(view: EditorView) {
    const host = document.createElement("div")
    host.dataset.slot = "markdown-table-widget"
    host.contentEditable = "false"
    this.store.set({ kind: "table", host, view, source: this.source })
    return host
  }
  override ignoreEvent(event: Event) {
    return event.type !== "mousedown"
  }
  override destroy(dom: HTMLElement) {
    this.store.delete(dom)
  }
}

export { BulletWidget, CodeLanguageWidget, LabelWidget, PortalStore, TableWidget, TaskWidget }
export type { PortalEntry }

"use client"

import { EditorView } from "@codemirror/view"
import type { TextEditorAdapter } from "@ui-sdk/react/trigger-menu"
import { useEffect, useEffectEvent, useLayoutEffect, useRef, useState, type RefObject } from "react"

import type { MarkdownEditorProps } from "@/components/ui/markdown-editor"
import { createAdapterBridge } from "@/components/ui/markdown-editor-adapter"
import { createEditorState, reconfigure, type EditorSettings } from "@/components/ui/markdown-editor-state"
import { useMarkdownSync } from "@/components/ui/markdown-editor-sync"

/**
 * Mounts a CodeMirror view in `hostRef` once, keeps its settings current, and feeds it each new `value`. Props
 * other than `value` are read when CodeMirror or the sync timers need them, so changing them never rebuilds it.
 */
function useMarkdownEditorView(props: MarkdownEditorProps, settings: EditorSettings) {
  const hostRef = useRef<HTMLDivElement>(null)
  const latest = useRef(props)
  const settingsRef = useRef(settings)
  const [view, setView] = useState<EditorView>()
  const [adapter, setAdapter] = useState<TextEditorAdapter>()
  const sync = useMarkdownSync(latest)
  const { value } = props

  // oxlint-disable-next-line p-otero/no-latest-ref-effect -- CodeMirror's listeners and the sync timers run outside React and read the newest props through these refs; useMarkdownSync takes them as a ref
  useLayoutEffect(() => {
    latest.current = props
    settingsRef.current = settings
  })

  useEffect(() => {
    const host = hostRef.current
    if (!host) return
    const bridge = createAdapterBridge()
    const hooks = {
      bridge: bridge.extension,
      onUpdate: sync.onUpdate,
      openWikilink: (slug: string) => latest.current.onOpenWikilink?.(slug),
    }
    const initial = latest.current.value ?? latest.current.defaultValue ?? ""
    const languages = latest.current.codeLanguages
    const editor = new EditorView({
      state: createEditorState(initial, settingsRef.current, hooks, languages),
      parent: host,
    })
    const detach = sync.attach(editor, initial, (markdown) =>
      editor.setState(createEditorState(markdown, settingsRef.current, hooks, languages)),
    )
    const attached = bridge.attach(editor)
    setView(editor)
    setAdapter(attached.adapter)
    return () => {
      detach()
      attached.detach()
      editor.destroy()
    }
  }, [sync])

  useEffect(() => {
    if (view) reconfigure(view, settings)
  }, [view, settings])

  useEffect(() => {
    if (view && value !== undefined) sync.receive(value)
  }, [view, value, sync])

  return { hostRef, view, adapter, sync }
}

/** Calls `onResize` with the element each time ResizeObserver reports it, starting with its first size. */
function useResizeObserver<Element extends HTMLElement>(
  ref: RefObject<Element | null>,
  onResize: (element: Element) => void,
) {
  const resized = useEffectEvent(onResize)
  useLayoutEffect(() => {
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => resized(element))
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
}

/** Asks CodeMirror to measure again after every render, since a widget's React content can change its height. */
function useRequestMeasure(view: EditorView) {
  useLayoutEffect(() => view.requestMeasure())
}

export { useMarkdownEditorView, useRequestMeasure, useResizeObserver }
